    #include <vector> // For std::vector
    #include <array>  // For std::array

    int main() {
        std::vector<int> vec = {1, 2, 3, 4, 5};
        // Using .at() provides bounds checking and throws an exception on error
        for (size_t i = 0; i < vec.size(); i++) {
            std::cout << vec.at(i) << std::endl; // Safe access
        }
        std::cout << "---" << std::endl;

        std::array<int, 5> arr_std = {1, 2, 3, 4, 5};
        for (int val : arr_std) { // Range-based for loop works great here
            std::cout << val << std::endl;
        }

        return 0;
    }
    ```

Always be mindful of array bounds to avoid undefined behavior, which is a common source of bugs in C and C++ programs!

